import { AxiosError } from 'axios';
import { Injectable, Logger } from '@nestjs/common';
import {
  defaultModerationFallback,
  moderationLabelToStatus,
  moderationStatusToVisibility,
} from './moderation.constants';
import {
  ModerationResult,
  PersistedModerationStatus,
  VisibilityLevel,
} from './interfaces/moderation-result.interface';
import { ModerationProvider } from './moderation.provider';
import {
  MediaModerationLabel,
  MediaModerationResult,
  MediaSafetyDecision,
  ModerateMediaRequest,
} from './interfaces/media-moderation.interface';

@Injectable()
export class ModerationService {
  private readonly logger = new Logger(ModerationService.name);
  private readonly unsafeImageThreshold = 0.7;
  private readonly unsafeVideoFrameRatioThreshold = 0.3;
  private readonly unsafeVideoSexyThreshold = 0.5;

  constructor(private readonly moderationProvider: ModerationProvider) {}

  async moderateText(text: string): Promise<ModerationResult> {
    const normalized = text.trim();
    if (!normalized) {
      return {
        ...defaultModerationFallback,
        text: normalized,
      };
    }

    try {
      const result = await this.moderationProvider.moderateText({
        text: normalized,
      });

      return this.normalizeResult(result);
    } catch (error) {
      this.logger.error(
        `AI moderation request failed. Fallback applied. ${this.formatError(error)}`,
      );

      return {
        ...defaultModerationFallback,
        text: normalized,
      };
    }
  }

  async moderateMedia(payload: ModerateMediaRequest): Promise<MediaModerationResult> {
    try {
      const raw = await this.moderationProvider.moderateMedia(payload);
      return this.normalizeMediaResult(payload.mediaKind, raw);
    } catch (error) {
      this.logger.error(`AI media moderation request failed. ${this.formatError(error)}`);
      return {
        mediaKind: payload.mediaKind,
        topLabel: 'unknown',
        topConfidence: 0,
        classes: [],
        unsafeFrameRatio: null,
        model: 'fallback',
        raw: null,
      };
    }
  }

  toVisibilityLevel(status: PersistedModerationStatus): VisibilityLevel {
    return moderationStatusToVisibility[status];
  }

  toMediaSafetyDecision(result: MediaModerationResult): MediaSafetyDecision {
    const classes = new Map(
      result.classes.map((entry) => [entry.label, this.clamp(entry.confidence)]),
    );
    const porn = classes.get('porn') ?? 0;
    const hentai = classes.get('hentai') ?? 0;
    const sexy = classes.get('sexy') ?? 0;
    const blood = classes.get('blood') ?? 0;

    if (result.mediaKind === 'image') {
      if (porn > 0 || hentai > 0) {
        return {
          policy: 'HARD_BLUR_EXPLICIT',
          reason: 'Nội dung nhạy cảm cao đã bị che mờ vĩnh viễn.',
          blurSuggested: true,
          requiresClickToReveal: false,
          visibleByDefault: false,
          blockedFromPosting: false,
        };
      }

      if (blood >= this.unsafeImageThreshold) {
        return {
          policy: 'BLUR_BLOOD_GORE',
          reason: 'Nội dung kinh dị, có thể gây ám ảnh.',
          blurSuggested: true,
          requiresClickToReveal: true,
          visibleByDefault: false,
          blockedFromPosting: false,
        };
      }

      if (sexy >= this.unsafeImageThreshold) {
        return {
          policy: 'BLUR_SUGGESTIVE_18',
          reason: 'Nội dung không phù hợp với người dưới 18 tuổi.',
          blurSuggested: true,
          requiresClickToReveal: true,
          visibleByDefault: false,
          blockedFromPosting: false,
        };
      }

      return this.normalMediaDecision();
    }

    if (porn > 0 || hentai > 0) {
      return {
        policy: 'BLOCKED_EXPLICIT_VIDEO',
        reason: 'Video chứa nội dung khiêu dâm/explicit nên không được phép đăng.',
        blurSuggested: false,
        requiresClickToReveal: false,
        visibleByDefault: false,
        blockedFromPosting: true,
      };
    }

    if (
      (result.unsafeFrameRatio ?? 0) >= this.unsafeVideoFrameRatioThreshold &&
      blood >= this.unsafeImageThreshold
    ) {
      return {
        policy: 'BLUR_BLOOD_GORE',
        reason: 'Nội dung kinh dị, có thể gây ám ảnh.',
        blurSuggested: true,
        requiresClickToReveal: true,
        visibleByDefault: false,
        blockedFromPosting: false,
      };
    }

    if (sexy > this.unsafeVideoSexyThreshold) {
      return {
        policy: 'BLOCKED_HIGH_SUGGESTIVE_VIDEO',
        reason: 'Video có mức gợi dục cao nên không được phép đăng.',
        blurSuggested: false,
        requiresClickToReveal: false,
        visibleByDefault: false,
        blockedFromPosting: true,
      };
    }

    return this.normalMediaDecision();
  }

  private normalizeResult(result: ModerationResult): ModerationResult {
    const finalLabel =
      result.final_label === 'clean' ||
      result.final_label === 'offensive' ||
      result.final_label === 'hate' ||
      result.final_label === 'discrimination' ||
      result.final_label === 'supportive' ||
      result.final_label === 'other'
        ? result.final_label
        : 'clean';
    const action =
      result.action === 'ALLOW' ||
      result.action === 'WARN_USER' ||
      result.action === 'BLOCK_OR_REVIEW'
        ? result.action
        : 'WARN_USER';
    const status =
      result.status === 'APPROVED' ||
      result.status === 'WARNING' ||
      result.status === 'FLAGGED' ||
      result.status === 'AI_UNAVAILABLE'
        ? result.status
        : moderationLabelToStatus[finalLabel];

    return {
      text: result.text ?? '',
      final_label: finalLabel,
      final_confidence: Number.isFinite(result.final_confidence) ? result.final_confidence : 0,
      is_warning: Boolean(result.is_warning),
      action,
      layers: Array.isArray(result.layers)
        ? result.layers.map((layer) => ({
            layer: layer.layer,
            task: layer.task ?? 'unknown',
            model: layer.model ?? 'unknown',
            input_text: layer.input_text,
            pred_id: layer.pred_id,
            label: layer.label,
            confidence: Number.isFinite(layer.confidence) ? layer.confidence : 0,
            probabilities: layer.probabilities ?? {},
            is_warning: Boolean(layer.is_warning),
          }))
        : [],
      status,
      model:
        result.model ||
        (Array.isArray(result.layers)
          ? result.layers
              .map((layer) => layer.model)
              .filter((model): model is string => typeof model === 'string' && model.length > 0)
              .join(',')
          : '') ||
        'fallback',
    };
  }

  private normalizeMediaResult(
    mediaKind: 'image' | 'video',
    result: Partial<MediaModerationResult>,
  ): MediaModerationResult {
    const classes = Array.isArray(result.classes)
      ? result.classes
          .filter(
            (entry): entry is { label: MediaModerationLabel; confidence: number } =>
              Boolean(entry && typeof entry.label === 'string' && typeof entry.confidence === 'number'),
          )
          .map((entry) => ({
            label: this.normalizeMediaLabel(entry.label),
            confidence: this.clamp(entry.confidence),
          }))
      : [];

    return {
      mediaKind,
      topLabel: this.normalizeMediaLabel(result.topLabel),
      topConfidence: this.clamp(result.topConfidence ?? 0),
      classes,
      unsafeFrameRatio:
        typeof result.unsafeFrameRatio === 'number' ? this.clamp(result.unsafeFrameRatio) : null,
      model: result.model && result.model.trim().length > 0 ? result.model : 'unknown',
      raw: result.raw ?? result,
    };
  }

  private normalizeMediaLabel(label: string | undefined): MediaModerationLabel {
    switch (label) {
      case 'neutral':
      case 'sexy':
      case 'porn':
      case 'hentai':
      case 'blood':
      case 'drawings':
        return label;
      default:
        return 'unknown';
    }
  }

  private normalMediaDecision(): MediaSafetyDecision {
    return {
      policy: 'NORMAL',
      reason: null,
      blurSuggested: false,
      requiresClickToReveal: false,
      visibleByDefault: true,
      blockedFromPosting: false,
    };
  }

  private clamp(value: number): number {
    if (!Number.isFinite(value)) {
      return 0;
    }

    if (value < 0) {
      return 0;
    }

    if (value > 1) {
      return 1;
    }

    return value;
  }

  private formatError(error: unknown): string {
    if (error instanceof AxiosError) {
      const responseStatus = error.response?.status;
      const responseData = error.response?.data;
      const responseText =
        responseData !== undefined ? JSON.stringify(responseData) : 'no_response_body';
      return [
        `code=${error.code ?? 'UNKNOWN'}`,
        `message=${error.message}`,
        `url=${error.config?.baseURL ?? ''}${error.config?.url ?? ''}`,
        `status=${responseStatus ?? 'NO_STATUS'}`,
        `response=${responseText}`,
      ].join(' ');
    }

    if (error instanceof Error) {
      return `message=${error.message}`;
    }

    return `error=${String(error)}`;
  }
}
